import plotly.graph_objects as go

total_failed = int(df['FAILED_TXN_CNT'].sum())
total_txns = int(df['TXN_CNT'].sum())
if total_txns > 0:
    pct = (total_failed / total_txns) * 100
else:
    pct = 0.0

fig = go.Figure(go.Indicator(
    mode='gauge+number',
    value=pct,
    number={'suffix': '%', 'valueformat': '.1f'},
    title={'text': 'Share of Failed Transactions (All Channels)'},
    gauge={
        'axis': {'range': [0, 100], 'ticksuffix': '%'},
        'bar': {'color': '#d62728'},
        'threshold': {'line': {'color': 'white', 'width': 4}, 'thickness': 0.75, 'value': 50}
    }
))
